var i=`0045-paczki`;var a=`world-0045`;var t=`PL`;var o=`eastern-europe`;var s=10;var r=109;var l={en:`Pączki`,ua:`Пончики пачкі`};var u={en:`A classic dish from Poland, featuring whole cow milk, chicken egg, all-purpose flour, instant yeast. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Польща. Основні складники: цільне коров'яче молоко, куряче яйце, пшеничне борошно універсальне, інстантні дріжджі. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 70 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 70 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:70,i:[[`all-purpose-flour`,450,`g`],[`whole-cow-milk`,230,`ml`],[`instant-yeast`,8,`g`],[`white-granulated-sugar`,75,`g`],[`chicken-egg`,2,`pcs`],[`unsalted-butter`,70,`g`],[`table-salt`,4,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:4,i:[[`strawberry-jam`,200,`g`]]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 20 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 20 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:20,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 12 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 12 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:12,i:[[`sunflower-oil`,700,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`powdered-sugar`,60,`g`]]}];var d={slug:i,id:a,country:`PL`,region:o,servings:10,minutes:109,title:l,text:u,steps:g};export{t as country,d as default,a as id,r as minutes,o as region,s as servings,i as slug,g as steps,u as text,l as title};